"""Verification harness (NOT part of the fix): force --assert=plain in pytester
inner runs. pytest 6.0's assertion rewriter is incompatible with Python 3.12's
AST (TypeError: required field "lineno" missing from alias), which breaks all
pytester-based tests on this machine regardless of the caplog fix.
"""


def _patch():
    import _pytest.pytester as pytester_mod

    for method_name in ("runpytest_inprocess", "runpytest_subprocess"):
        orig = getattr(pytester_mod.Testdir, method_name)

        def make_patched(orig):
            def patched(self, *args, **kwargs):
                args = tuple(args)
                if "--assert=plain" not in args:
                    args = args + ("--assert=plain",)
                return orig(self, *args, **kwargs)

            return patched

        setattr(pytester_mod.Testdir, method_name, make_patched(orig))


_patch()

